 public class CitySubtitleFilter{

 private Map<String, Set<Integer>> subtitleMap = new HashMap<>();

  public void submapAdd(String city, int index){
     if (!subtitleMap.containsKey(city)) {
         subtitleMap.put(city, new HashSet<>());
     }
     subtitleMap.get(city).add(index);
 }



    public List<CitySubtitleMap> findSubtitles(String city, Integer startIndex, Integer endIndex) {
        List<CitySubtitleMap> result = new ArrayList<>();
        for (Map.Entry<String, Set<Integer>> entry : subtitleMap.entrySet()) {
            String cityName = entry.getKey();
            Set<Integer> indices = entry.getValue();

            List<Integer> foundIndices = new ArrayList<>();
            for (int idx : indices) {
                if (idx >= startIndex && idx <= endIndex) {
                    foundIndices.add(idx);
                }
            }
            if (!foundIndices.isEmpty()) {
                CitySubtitleMap map = new CitySubtitleMap();
                map.setCity(cityName);
                map.setSubindices(foundIndices);
                result.add(map);
            }
        }
        return result;
    }

 }



