()=>{

    const [subTitleList, setSubTitleList] = useState([]);


    let diff_values = [];
    let triggers = [];

    function computeDifferentiation(tokenValues) {
        var delta = {};
        var prevValue = undefined;
        tokenValues.forEach(function(value, index) {
            if (index > 0) {
                var difference = value - prevValue;
                if (difference != 0) {
                    delta[index] = difference;
                    triggers.push({ index: index, value: value });
                }
            }
            prevValue = value;
        });
        return { values: tokenValues, delta: delta };
    }

     useEffect(() => {
        fetch("api/subtitles")
          .then(response => response.json())
          .then(data => {
              setSubTitleList(data.result);

              const transformedData = computeDifferentiation(subTitleList);
              diff_values = transformedData.delta;
          })
          .catch(error => console.error('Error fetching data:', error));
     }, []);

     if (subTitleList.length === 0)
         return <div>No subtitles found.</div>;

     const handleCardClick = (index) => {
         // Handle click logic
     };

     return (
         <div className="container">
             {subTitleList.map((item, index) => {
                 const {values, delta} = computeDifferentiation(item.sub_titles);
                 return (
                     <div key={index}>
                         <p>{item.city}</p>

                         <div className="card">
                             <img src={item.image_url} alt={item.title} />
                             <div className="card-content">
                                 <p>Subtitle: {item.subtitle_title}</p>
                                 <p>Count: {values.length}</p>
                                 <span style={{ color: '#FF6347' }}>Difference: {delta[index]}</span>
                                 <button onClick={() => handleCardClick(index)}>View Details</button>
                             </div>
                         </div>
                     </div>
                 );
             })}
         </div>
     );
}




